fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>
) {
    let n = vals_1.len();
    // All input vectors must have the same length
    assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");

    // Overwrite any previous contents
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let use_1 = conds_1[i];
        let use_2 = conds_2[i];
        let value = if use_1 && use_2 {
            // both true: average
            (vals_1[i] + vals_2[i]) / 2
        } else if use_1 {
            // only first is true
            vals_1[i]
        } else {
            // only second is true (guaranteed by problem statement)
            vals_2[i]
        };
        avgs.push(value);
    }
}